head.b:skin:
/*
  Saeium Blogger Theme 1.0.0
  Original editorial design inspired by the structure of medium.com.
  No Medium marks, source code, articles or images are included.
*/
:root{--ink:#242424;--muted:#6b6b6b;--line:#e7e7e7;--paper:#fff;--cream:#f7f4ed;--accent:#1f7a4d;--max:1200px;--reading:680px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.55 Arial,Helvetica,sans-serif}img{max-width:100%;height:auto}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.wrap{width:min(calc(100% - 48px),var(--max));margin-inline:auto}.sr-only{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}
.site-header{height:76px;border-bottom:1px solid var(--ink);background:var(--cream);position:relative;z-index:20}.site-header .wrap{height:100%;display:flex;align-items:center;gap:28px}.brand{margin-right:auto;min-width:0}.brand .Header{margin:0}.brand a{display:inline-flex;align-items:center}.brand h1,.brand .title{font:700 34px/1 Georgia,'Times New Roman',serif;letter-spacing:-.06em;margin:0}.brand img{display:block;max-width:190px;max-height:48px;object-fit:contain}.main-nav .widget{margin:0}.main-nav ul,.footer-links ul{display:flex;align-items:center;gap:28px;list-style:none;margin:0;padding:0}.main-nav a{font-size:14px;white-space:nowrap}.header-tools{display:flex;align-items:center;gap:12px}.icon-button{border:0;background:none;display:inline-grid;place-items:center;width:42px;height:42px;border-radius:50%;font-size:23px;line-height:1}.icon-button:hover{background:#e8e4dc}.header-cta,.pill{display:inline-flex;justify-content:center;align-items:center;border-radius:999px;background:var(--ink);color:#fff;padding:10px 20px;font-size:14px;line-height:1.3}.header-cta:hover,.pill:hover{background:#3e3e3e;text-decoration:none}.menu-toggle{display:none}.search-panel{display:none;position:absolute;top:75px;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 12px 20px #0001}.search-panel.is-open{display:block}.search-panel form{display:flex;gap:12px;padding:18px 0}.search-panel input{flex:1;min-width:0;border:1px solid var(--line);border-radius:4px;padding:11px 14px}.search-panel button{border:0}
.hero{display:none;background:var(--cream);border-bottom:1px solid var(--ink)}.hero-inner{min-height:570px;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:65px 0}.hero h2{font:400 clamp(72px,9.5vw,120px)/.87 Georgia,'Times New Roman',serif;letter-spacing:-.075em;max-width:800px;margin:0 0 45px}.hero p{font-size:22px;line-height:1.3;max-width:720px;margin:0 0 35px}.hero .pill{font-size:18px;padding:13px 34px}.hero .widget{width:100%}
.topic-strip{border-bottom:1px solid var(--line);padding:24px 0}.topic-strip .widget{display:flex;align-items:center;gap:20px}.topic-strip h2{font-size:13px;text-transform:uppercase;letter-spacing:.08em;white-space:nowrap;margin:0}.topic-strip ul{display:flex;gap:9px;overflow:auto;list-style:none;margin:0;padding:0;scrollbar-width:thin}.topic-strip li{flex:none}.topic-strip a,.tag-list a{display:inline-block;background:#f2f2f2;padding:7px 15px;border-radius:999px;font-size:13px;white-space:nowrap}.topic-strip a:hover,.tag-list a:hover{background:#e7e7e7;text-decoration:none}
.content-shell{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:68px;align-items:start;padding-top:46px;padding-bottom:90px}.content-main{min-width:0}.section-label{font-size:15px;font-weight:700;margin:0 0 20px}.trend-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px;border-bottom:1px solid var(--line);padding:0 0 38px;margin:0 0 34px;list-style:none;counter-reset:trend}.trend-list li{position:relative;padding-left:43px;counter-increment:trend}.trend-list li:before{content:counter(trend,decimal-leading-zero);position:absolute;left:0;top:0;color:#d1d1d1;font-size:26px;font-weight:700}.trend-list a{font-size:15px;line-height:1.3;font-weight:700}.trend-list small{display:block;color:var(--muted);font-size:12px;margin-top:9px}.archive-title{font-size:34px;line-height:1.2;letter-spacing:-.04em;margin:0 0 24px}.story-card{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:28px;padding:25px 0;border-bottom:1px solid var(--line)}.story-card:first-child{padding-top:0}.story-meta,.story-date{font-size:13px;color:var(--muted)}.story-meta{font-weight:600;color:var(--ink)}.story-title{font-size:24px;line-height:1.22;letter-spacing:-.025em;margin:8px 0}.story-snippet{font-size:16px;color:var(--muted);line-height:1.45;margin:0 0 14px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}.story-image{width:180px;height:120px;object-fit:cover;background:#e9e9e9}.story-image.empty{display:grid;place-items:center;font:italic 26px Georgia,serif;color:#888}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:32px}.pager a{border:1px solid var(--line);border-radius:999px;padding:9px 18px;font-size:14px}
.sidebar{border-left:1px solid var(--line);padding-left:34px}.sidebar .widget{margin-bottom:44px}.sidebar h2{font-size:16px;margin:0 0 18px}.sidebar .Label ul{list-style:none;display:flex;flex-wrap:wrap;gap:8px;padding:0;margin:0}.sidebar .Label a{display:inline-block;background:#f2f2f2;border-radius:999px;padding:6px 13px;font-size:13px}.sidebar .HTML{font-size:14px;color:var(--muted)}.sidebar .HTML p{margin-top:0}
.post-page{max-width:var(--reading);margin:0 auto}.post-title{font-size:42px;line-height:1.19;letter-spacing:-.035em;margin:15px 0 18px}.post-subtitle{font-size:19px;color:var(--muted)}.post-byline{display:flex;gap:10px;align-items:center;color:var(--muted);font-size:14px;margin:22px 0}.post-byline strong{color:var(--ink)}.post-tools{display:flex;justify-content:flex-end;gap:14px;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:22px 0 36px}.post-tools button{border:0;background:none;color:var(--muted)}.post-body{font:20px/1.8 Georgia,'Times New Roman',serif;overflow-wrap:anywhere}.post-body p{margin:0 0 1.35em}.post-body h2{font:700 28px/1.3 Arial,Helvetica,sans-serif;margin:1.7em 0 .5em}.post-body h3{font:700 22px/1.35 Arial,Helvetica,sans-serif}.post-body blockquote{border-left:3px solid var(--ink);margin:1.5em 0;padding-left:22px;font-style:italic}.post-body a{text-decoration:underline}.post-body img{display:block;margin:25px auto}.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin:40px 0}.post-comments{border-top:1px solid var(--line);padding-top:22px}.post-comments a{display:inline-block;border:1px solid var(--line);padding:8px 15px;border-radius:999px}
.site-footer{border-top:1px solid var(--ink);background:var(--cream);padding:28px 0}.site-footer .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px}.footer-links ul{gap:16px;flex-wrap:wrap}.footer-links a,.credit{font-size:12px;color:var(--muted)}.credit a{text-decoration:underline}
.error-panel{padding:100px 0;max-width:680px}.error-panel h1{font:400 65px/.95 Georgia,serif}.notice{padding:28px;background:#f6f6f6;color:var(--muted)}
@media(max-width:900px){.content-shell{grid-template-columns:1fr;gap:34px}.sidebar{border-left:0;border-top:1px solid var(--line);padding:30px 0 0}.trend-list{gap:16px}.site-footer .wrap{align-items:flex-start;flex-direction:column}}
@media(max-width:680px){.wrap{width:min(calc(100% - 40px),var(--max))}.site-header{height:72px}.site-header .wrap{gap:8px}.brand h1,.brand .title{font-size:31px}.brand img{max-width:150px;max-height:42px}.main-nav{display:none;position:absolute;top:71px;left:0;right:0;background:var(--cream);border-bottom:1px solid var(--ink);padding:18px 20px}.main-nav.is-open{display:block}.main-nav ul{align-items:flex-start;flex-direction:column;gap:15px}.menu-toggle{display:inline-grid}.header-cta{display:none}.search-panel{top:71px}.hero-inner{min-height:650px;padding:70px 0}.hero h2{font-size:clamp(65px,18vw,80px);line-height:.9;letter-spacing:-.07em;margin-bottom:34px}.hero p{font-size:20px;line-height:1.35}.content-shell{padding-top:32px}.trend-list{grid-template-columns:1fr;gap:18px}.story-card{grid-template-columns:minmax(0,1fr) 96px;gap:14px}.story-image{width:96px;height:96px}.story-title{font-size:19px}.story-snippet{font-size:14px}.archive-title{font-size:26px}.post-title{font-size:32px;line-height:1.2}.post-body{font-size:18px;line-height:1.7}.topic-strip .widget{display:block}.topic-strip h2{margin-bottom:12px}}
@media(max-width:350px){.hero h2{font-size:60px}.story-card{grid-template-columns:minmax(0,1fr) 80px}.story-image{width:80px;height:80px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
  
/* TB:NEWS_INDEX:CSS:START */
/* TemaBlogger shared News Index v1.0.0. Theme color and font are inherited. */
.tbni{--tbni-accent:var(--red,#df1529);--tbni-ink:var(--ink,#25272a);--tbni-line:#e7e8eb;color:var(--tbni-ink);margin:26px 0 40px;font-family:inherit;min-width:0}
.tbni *{box-sizing:border-box}
.tbni[hidden],.tbni [hidden]{display:none!important}
.tbni a{color:inherit;text-decoration:none}
.tbni .tbni-breadcrumb{display:flex;gap:8px;align-items:center;color:#82858c;font-size:11px;margin-bottom:18px}
.tbni-breadcrumb a:hover{color:var(--tbni-accent)}
.tbni .tbni-heading{font-size:36px;font-weight:800;letter-spacing:-1.1px;line-height:1.2;margin:0 0 12px}
.tbni-intro{font-size:13px;line-height:1.8;color:#777b83;margin:0 0 26px;max-width:560px}
.tbni-intro:before{content:"";display:block;width:42px;height:4px;background:var(--tbni-accent);margin:18px 0;border-radius:2px}
.tbni .tbni-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 118px;gap:14px;align-items:end;padding:20px;background:#f7f8fa;border:1px solid #eceef1;border-radius:10px;margin:0 0 18px}
.tbni-field{display:block;min-width:0;font-size:11px;font-weight:600}
.tbni-field>span{display:block;margin-bottom:8px}
.tbni-control{position:relative;display:flex;align-items:center;min-width:0}
.tbni-control>.tbni-icon{position:absolute;left:12px;width:19px;height:19px;pointer-events:none;color:#858994}
.tbni input,.tbni select,.tbni button{font-family:inherit;font-size:12px}
.tbni input,.tbni select{width:100%;min-width:0;max-width:100%;height:44px;border:1px solid #dfe2e7;border-radius:6px;background:#fff;color:var(--tbni-ink);padding:0 10px 0 39px;line-height:normal}
.tbni select{padding-right:25px;text-overflow:ellipsis}
.tbni input[type=date]{color-scheme:light}
.tbni .tbni-submit{height:44px;border:1px solid var(--tbni-accent);border-radius:6px;background:var(--tbni-accent);color:#fff;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}
.tbni-icon{display:inline-block;width:20px;height:20px;fill:currentColor;flex-shrink:0;vertical-align:middle}
.tbni-channels{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:1px 1px 12px;margin-bottom:12px}
.tbni-channels::-webkit-scrollbar{display:none}
.tbni .tbni-chip{flex-shrink:0;white-space:nowrap;border:1px solid #e3e5e9;border-radius:20px;padding:8px 14px;color:#676b73;background:#fff;cursor:pointer;font-size:11px;line-height:1.4}
.tbni .tbni-chip[aria-pressed=true]{border-color:var(--tbni-accent);color:var(--tbni-accent);background:color-mix(in srgb,var(--tbni-accent) 6%,white);font-weight:600}
.tbni-summary{display:flex;justify-content:space-between;gap:14px;align-items:center;border-bottom:1px solid var(--tbni-line);padding-bottom:16px;margin-bottom:24px}
.tbni .tbni-count{font-weight:700;font-size:14px;margin:0 0 4px}
.tbni-context{font-size:11px;line-height:1.6;color:#8a8d94;margin:0}
.tbni .tbni-reset{background:none;border:0;color:var(--tbni-accent);padding:8px 0 8px 8px;min-height:40px;cursor:pointer;font-size:11px;white-space:nowrap}
.tbni .tbni-day{margin-bottom:26px}
.tbni .tbni-date{display:flex;align-items:center;gap:9px;font-size:14px;font-weight:700;line-height:1.5;margin:0;padding:12px 14px;background:#f5f6f8;border-left:3px solid var(--tbni-accent);border-radius:0 5px 5px 0}
.tbni-date .tbni-icon{width:18px;height:18px;color:var(--tbni-accent)}
.tbni .tbni-row{display:grid;grid-template-columns:58px minmax(0,1fr) 132px;gap:18px;align-items:center;padding:21px 0;border-bottom:1px solid var(--tbni-line)}
.tbni-time{align-self:start;padding-top:3px;font-size:12px;font-weight:600;color:#858994;line-height:1.6;font-variant-numeric:tabular-nums}
.tbni-time small{display:block;font-size:9px;font-weight:400;letter-spacing:.4px;color:#a1a4aa;margin-top:2px}
.tbni-copy{min-width:0}
.tbni .tbni-category{display:inline-block;color:var(--tbni-accent);font-size:10px;font-weight:600;margin:0 0 7px;line-height:1.4}
.tbni .tbni-title{font-size:16px;font-weight:700;line-height:1.55;letter-spacing:-.15px;margin:0;overflow-wrap:anywhere}
.tbni-title a:hover{color:var(--tbni-accent)}
.tbni .tbni-photo{display:grid;place-items:center;aspect-ratio:16/10;align-self:start;overflow:hidden;border-radius:6px;background:#f0f1f4;color:#b2b5bc}
.tbni-photo img{display:block;width:100%;height:100%;object-fit:cover}
.tbni-photo>.tbni-icon{width:30px;height:30px}
.tbni-more-area{text-align:center;padding:4px 0}
.tbni-progress{color:#8a8d94;font-size:11px;line-height:1.6;margin:0 0 14px}
.tbni .tbni-more,.tbni .tbni-retry{display:inline-flex;justify-content:center;align-items:center;gap:10px;border:1px solid var(--tbni-accent);border-radius:6px;min-height:44px;background:#fff;color:var(--tbni-accent);padding:10px 24px;font-size:12px;font-weight:600;cursor:pointer}
.tbni button:disabled{opacity:.55;cursor:wait}
.tbni button:focus-visible,.tbni input:focus-visible,.tbni select:focus-visible,.tbni a:focus-visible{outline:2px solid var(--tbni-accent);outline-offset:3px}
.tbni .tbni-notice{padding:32px 20px;border:1px solid var(--tbni-line);background:#fafbfc;border-radius:8px;text-align:center;margin-bottom:22px}
.tbni-notice>.tbni-icon{width:36px;height:36px;color:#afb3bd;margin-bottom:8px}
.tbni .tbni-notice h2{font-size:17px;line-height:1.5;margin:0 0 8px}
.tbni .tbni-notice p{font-size:12px;line-height:1.8;color:#80848d;margin:0 0 16px}
.tbni .tbni-native-link{display:block;font-size:11px;color:#80848d;margin-top:14px;text-decoration:underline}
.tbni-loading .tbni-ghost{height:120px;border-bottom:1px solid var(--tbni-line);background:linear-gradient(90deg,#f4f5f7 0 9%,transparent 9% 13%,#f4f5f7 13% 75%,transparent 75%);margin:0 0 12px;opacity:.7}
.has-tb-news-index .tb-index-native{display:none}
@media(max-width:600px){
 .tbni{margin-top:22px}
 .tbni .tbni-heading{font-size:30px;letter-spacing:-.8px}
 .tbni-intro{font-size:12px;margin-bottom:22px}
 .tbni .tbni-form{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 10px;padding:16px}
 .tbni .tbni-submit{grid-column:1/-1}
 .tbni input,.tbni select{font-size:11px;padding-left:32px}
 .tbni-control>.tbni-icon{left:9px;width:17px;height:17px}
 .tbni input[type=date]{padding-right:4px}
 .tbni .tbni-row{grid-template-columns:39px minmax(0,1fr) 86px;gap:10px;padding:18px 0}
 .tbni .tbni-title{font-size:13px;line-height:1.6;letter-spacing:-.1px}
 .tbni-time{font-size:10px}
 .tbni-time small{font-size:8px}
 .tbni .tbni-category{font-size:9px;margin-bottom:5px}
 .tbni .tbni-date{font-size:12px;padding:11px 10px}
 .tbni .tbni-count{font-size:13px}
 .tbni-context{font-size:10px}
 .tbni .tbni-photo{border-radius:5px}
}
@media(max-width:360px){.tbni .tbni-row{grid-template-columns:35px minmax(0,1fr) 72px;gap:8px}.tbni .tbni-title{font-size:12px}.tbni .tbni-form{padding:12px;gap:12px 8px}.tbni input,.tbni select{padding-left:28px}.tbni-control>.tbni-icon{left:7px;width:16px;height:16px}}
/* TB:NEWS_INDEX:CSS:END */

head.b:template-skin:
body#layout .site-header,body#layout .hero,body#layout .topic-strip,body#layout .content-shell,body#layout .site-footer{display:block!important;height:auto!important;min-height:0!important;position:static!important;background:#fff!important;padding:10px!important}
body#layout .wrap,body#layout .hero-inner{display:block!important;width:auto!important;min-height:0!important;padding:0!important}
body#layout .main-nav,body#layout .sidebar{display:block!important;position:static!important;border:0!important}
body#layout .content-shell{display:grid!important;grid-template-columns:minmax(0,2fr) minmax(250px,1fr)!important;gap:18px!important}
body#layout .section{padding:14px!important;margin:8px 0 18px!important;border:1px solid #d8dfda!important;border-radius:8px;background:#f8fbf8!important}
body#layout .section h4{font-size:14px!important;font-weight:700!important}
body#layout .widget{border:1px solid #e6e8e6!important;background:#fff!important;padding:10px!important;margin:8px 0!important}
body#layout .add_widget{display:none!important}

body.script:
//
/* TemaBlogger shared News Index v1.0.0. Pictogrammers MDI paths: Apache 2.0. */
(function(global){
'use strict';
const iconPaths={"calendar-month-outline":["M7 11H9V13H7V11M21 5V19C21 20.11 20.11 21 19 21H5C3.89 21 3 20.1 3 19V5C3 3.9 3.9 3 5 3H6V1H8V3H16V1H18V3H19C20.11 3 21 3.9 21 5M5 7H19V5H5V7M19 19V9H5V19H19M15 13V11H17V13H15M11 13V11H13V13H11M7 15H9V17H7V15M15 17V15H17V17H15M11 17V15H13V17H11Z"],"filter-variant":["M6,13H18V11H6M3,6V8H21V6M10,18H14V16H10V18Z"],"newspaper-variant-outline":["M20 5L20 19L4 19L4 5H20M20 3H4C2.89 3 2 3.89 2 5V19C2 20.11 2.89 21 4 21H20C21.11 21 22 20.11 22 19V5C22 3.89 21.11 3 20 3M18 15H6V17H18V15M10 7H6V13H10V7M12 9H18V7H12V9M18 11H12V13H18V11Z"],"chevron-right":["M8.59,16.58L13.17,12L8.59,7.41L10,6L16,12L10,18L8.59,16.58Z"],"chevron-down":["M7.41,8.58L12,13.17L16.59,8.58L18,10L12,16L6,10L7.41,8.58Z"]};
const esc=value=>String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>'<svg class="tbni-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" data-icon="mdi:'+esc(name)+'">'+(iconPaths[name]||[]).map(d=>'<path d="'+esc(d)+'"></path>').join('')+'</svg>';
function safeURL(value,base){if(!String(value||'').trim())return '';try{const u=new URL(value,base);return /^https?:$/.test(u.protocol)?u.href:'';}catch(e){return '';}}
function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return '';const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value?value:'';}
function dayBounds(value,offset='+07:00'){
 const day=validDate(value);if(!day)return null;
 if(!/^[+-](?:0\d|1[0-4]):[0-5]\d$/.test(offset))throw Error('Invalid news index date offset');
 return {min:day+'T00:00:00'+offset,max:day+'T23:59:59.999'+offset};
}
function isIndexRoute(url){
 const u=new URL(url),p=u.searchParams;
 return u.pathname.replace(/\/$/,'')==='/search'&&(p.get('view')==='index'||(!p.has('q')&&!['updated-max','updated-min','max-results','start'].some(k=>p.has(k))));
}
function feedURL(origin,filters,start=1,size=20,full=false,offset='+07:00'){
 const label=String(filters.label||'').trim(),u=new URL('/feeds/posts/'+(full?'default':'summary')+(label?'/-/'+encodeURIComponent(label):''),origin);
 u.searchParams.set('alt','json');u.searchParams.set('orderby','published');u.searchParams.set('max-results',String(size));u.searchParams.set('start-index',String(start));
 const bounds=dayBounds(filters.date,offset);if(bounds){u.searchParams.set('published-min',bounds.min);u.searchParams.set('published-max',bounds.max);}
 return u;
}
function dateKey(value,timeZone='Asia/Jakarta'){
 const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d),get=name=>parts.find(p=>p.type===name)?.value;
 return [get('year'),get('month'),get('day')].join('-');
}
function imageURL(value,origin){const safe=safeURL(value,origin);if(!safe)return '';const u=new URL(safe);if(/(^|\.)(blogger\.googleusercontent\.com|blogspot\.com|googleusercontent\.com|ggpht\.com)$/.test(u.hostname))u.pathname=u.pathname.replace(/\/(s\d+|w\d+(?:-h\d+)?)(?:-[^/]*)?\//,'/w320-h200-p-k-no-nu/');return u.href;}
function mount(root,options={}){
 if(!root||root.dataset.tbniReady||!isIndexRoute(location.href))return null;
 const cfg={timeZone:'Asia/Jakarta',dateOffset:'+07:00',timeLabel:'WIB',pageSize:20,labels:[],...options};
 const labels=[...new Set(cfg.labels.map(l=>String(l).trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));
 const $=selector=>root.querySelector(selector),$$=selector=>Array.from(root.querySelectorAll(selector));
 const prettyDay=key=>new Intl.DateTimeFormat('id-ID',{timeZone:'UTC',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(key+'T12:00:00Z'));
 root.classList.add('tbni');root.dataset.tbniReady='yes';
 root.innerHTML='<nav class="tbni-breadcrumb" aria-label="Jejak navigasi"><a href="/">Beranda</a>'+icon('chevron-right')+'<span>Indeks Berita</span></nav>'+
 '<header><h1 class="tbni-heading">Indeks Berita</h1><p class="tbni-intro">Temukan berita yang Anda cari. Telusuri kabar terbaru berdasarkan tanggal dan kanal pilihan.</p></header>'+
 '<form class="tbni-form"><label class="tbni-field"><span>Tanggal terbit</span><div class="tbni-control">'+icon('calendar-month-outline')+'<input type="date" name="tanggal" aria-label="Tanggal terbit"/></div></label>'+
 '<label class="tbni-field"><span>Kanal berita</span><div class="tbni-control">'+icon('newspaper-variant-outline')+'<select name="kanal" aria-label="Kanal berita"><option value="">Semua kanal</option>'+labels.map(l=>'<option value="'+esc(l)+'">'+esc(l)+'</option>').join('')+'</select></div></label>'+
 '<button class="tbni-submit" type="submit">'+icon('filter-variant')+'Tampilkan</button></form>'+
 '<div class="tbni-channels" role="group" aria-label="Pilih kanal">'+['',...labels].map(l=>'<button type="button" class="tbni-chip" data-channel="'+esc(l)+'" aria-pressed="false">'+esc(l||'Semua kanal')+'</button>').join('')+'</div>'+
 '<div class="tbni-summary"><div><p class="tbni-count" role="status" aria-live="polite"></p><p class="tbni-context"></p></div><button class="tbni-reset" type="button">Reset filter</button></div>'+
 '<div class="tbni-notices"></div><div class="tbni-results" aria-busy="false"></div><div class="tbni-more-area"><p class="tbni-progress" role="status"></p><button class="tbni-more" type="button">Muat berita lainnya '+icon('chevron-down')+'</button></div>';
 const form=$('.tbni-form'),dateInput=$('input[name=tanggal]'),channelInput=$('select[name=kanal]'),results=$('.tbni-results'),more=$('.tbni-more');
 let sequence=0,controller=null,next=1,total=null,loaded=0,activeFilters={date:'',label:''},hasMore=false;
 const seen=new Set(),groups=new Map();
 const readURL=()=>{const p=new URL(location.href).searchParams;dateInput.value=validDate(p.get('tanggal'));const label=p.get('kanal')||'';if(label&&!labels.includes(label)&&!Array.from(channelInput.options).some(o=>o.value===label)){const option=document.createElement('option');option.value=label;option.textContent=label;channelInput.add(option);}channelInput.value=label;};
 function updateURL(){const u=new URL(location.href);u.searchParams.set('view','index');for(const [name,value] of [['tanggal',dateInput.value],['kanal',channelInput.value]]){if(value)u.searchParams.set(name,value);else u.searchParams.delete(name);}if(u.href!==location.href)history.pushState(null,'',u);}
 function filterContext(){const date=activeFilters.date?prettyDay(activeFilters.date):'Semua tanggal',label=activeFilters.label||'Semua kanal';$('.tbni-context').textContent=date+' · '+label+' · '+cfg.timeLabel;$$('.tbni-chip').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.channel===activeFilters.label)));}
 function notice(title,message,retry=false){$('.tbni-notices').innerHTML='<div class="tbni-notice"'+(retry?' role="alert"':'')+'>'+icon('newspaper-variant-outline')+'<h2>'+esc(title)+'</h2><p>'+esc(message)+'</p>'+(retry?'<button type="button" class="tbni-retry">Coba lagi</button>':'<button type="button" class="tbni-retry">Lihat semua berita</button>')+'<a class="tbni-native-link" href="/search?max-results=20">Buka arsip biasa</a></div>';$('.tbni-retry').addEventListener('click',()=>{if(retry)load(loaded===0);else reset();});}
 function normalize(entry){
  const url=safeURL(entry.link?.find(l=>l.rel==='alternate')?.href||'',location.origin),published=entry.published?.$t||'';if(!url||!dateKey(published,cfg.timeZone))return null;
  let image=entry.media$thumbnail?.url||'';if(!image){const doc=new DOMParser().parseFromString(entry.content?.$t||entry.summary?.$t||'','text/html');image=doc.querySelector('img')?.getAttribute('src')||'';}
  return {id:entry.id?.$t||new URL(url).pathname,url,title:entry.title?.$t||'Tanpa judul',published,label:activeFilters.label||entry.category?.[0]?.term||'Berita',image:imageURL(image,location.origin)};
 }
 function append(post){
  if(seen.has(post.id))return;seen.add(post.id);const day=dateKey(post.published,cfg.timeZone);let list=groups.get(day);
  if(!list){const section=document.createElement('section');section.className='tbni-day';section.dataset.date=day;section.innerHTML='<h2 class="tbni-date">'+icon('calendar-month-outline')+esc(prettyDay(day))+'</h2><div class="tbni-day-list"></div>';results.append(section);list=section.lastElementChild;groups.set(day,list);}
  const time=new Intl.DateTimeFormat('id-ID',{timeZone:cfg.timeZone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(post.published)).replace('.',':');
  const row=document.createElement('article');row.className='tbni-row';row.dataset.postId=post.id;
  row.innerHTML='<time class="tbni-time" datetime="'+esc(post.published)+'">'+esc(time)+'<small>'+esc(cfg.timeLabel)+'</small></time><div class="tbni-copy"><a class="tbni-category" href="/search/label/'+encodeURIComponent(post.label)+'">'+esc(post.label)+'</a><h3 class="tbni-title"><a href="'+esc(post.url)+'">'+esc(post.title)+'</a></h3></div><a class="tbni-photo" href="'+esc(post.url)+'" aria-label="'+esc(post.title)+'" tabindex="-1">'+(post.image?'<img src="'+esc(post.image)+'" width="320" height="200" loading="lazy" decoding="async" alt=""/>':icon('newspaper-variant-outline'))+'</a>';
  list.append(row);loaded++;
 }
 async function load(restart=false){
  const run=++sequence;controller?.abort();controller=new AbortController();const currentController=controller,timer=setTimeout(()=>currentController.abort(),12000);
  if(restart){next=1;total=null;loaded=0;seen.clear();groups.clear();activeFilters={date:validDate(dateInput.value),label:channelInput.value.trim()};results.innerHTML='<div class="tbni-loading" aria-hidden="true"><div class="tbni-ghost"></div><div class="tbni-ghost"></div><div class="tbni-ghost"></div></div>';$('.tbni-count').textContent='Memuat berita…';filterContext();}
  $('.tbni-notices').innerHTML='';results.setAttribute('aria-busy','true');more.disabled=true;more.hidden=restart;$('.tbni-progress').textContent=restart?'':'Memuat berita berikutnya…';
  const get=async full=>{const response=await fetch(feedURL(location.origin,activeFilters,next,cfg.pageSize,full,cfg.dateOffset),{signal:currentController.signal});if(!response.ok)throw Error('Feed unavailable');const data=await response.json();if(!data.feed)throw Error('Invalid feed');return data.feed;};
  try{
   const data=await get(false);if(run!==sequence)return;const raw=data.entry||[];let posts=raw.map(normalize).filter(Boolean);
   if(posts.some(p=>!p.image)){try{const full=await get(true),images=new Map((full.entry||[]).map(normalize).filter(Boolean).map(p=>[p.id,p.image]));posts=posts.map(p=>p.image?p:{...p,image:images.get(p.id)||''});}catch(e){if(run!==sequence)return;}}
   if(run!==sequence)return;
   if(restart)results.innerHTML='';
   total=Number.parseInt(data.openSearch$totalResults?.$t,10);if(!Number.isFinite(total)||total<0)total=null;
   posts.forEach(append);next+=raw.length;hasMore=raw.length>0&&(total===null?raw.length===cfg.pageSize:next<=total);
   $('.tbni-count').textContent=total===null?loaded+' berita ditampilkan':total.toLocaleString('id-ID')+' berita ditemukan';
   $('.tbni-progress').textContent=loaded?'Menampilkan '+loaded.toLocaleString('id-ID')+(total===null?'':' dari '+total.toLocaleString('id-ID'))+' berita'+(hasMore?'':' · Anda sudah sampai di akhir daftar.'):'';
   more.hidden=!hasMore;
   if(!loaded)notice('Belum ada berita yang cocok','Coba tanggal atau kanal lain untuk menemukan berita yang Anda cari.');
  }catch(e){if(run!==sequence)return;if(restart)results.innerHTML='';$('.tbni-count').textContent=loaded?loaded+' berita ditampilkan':'Berita belum dapat dimuat';$('.tbni-progress').textContent='';notice('Berita belum dapat dimuat','Silakan coba lagi. Pilihan tanggal dan kanal Anda tetap tersimpan.',true);more.hidden=true;
  }finally{clearTimeout(timer);if(run===sequence){results.setAttribute('aria-busy','false');more.disabled=false;}}
 }
 function apply(){if(!form.reportValidity())return;updateURL();load(true);}
 function reset(){dateInput.value='';channelInput.value='';apply();}
 form.addEventListener('submit',e=>{e.preventDefault();apply();});$('.tbni-reset').addEventListener('click',reset);more.addEventListener('click',()=>load(false));
 $$('.tbni-chip').forEach(b=>b.addEventListener('click',()=>{channelInput.value=b.dataset.channel;apply();}));
 root.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.closest('.tbni-photo'))e.target.closest('.tbni-photo').innerHTML=icon('newspaper-variant-outline');},true);
 addEventListener('popstate',()=>{readURL();load(true);});
 readURL();root.hidden=false;document.documentElement.classList.add('has-tb-news-index');load(true);
 return {reload:()=>load(true),reset};
}
const api={version:'1.0.0',mount,dayBounds,dateKey,feedURL,isIndexRoute,imageURL};
if(typeof module==='object'&&module.exports)module.exports=api;else global.TBNewsIndex=api;
})(typeof window==='undefined'?{}:window);
/* TemaBlogger automatic News Index adapter v1.0.0 */
(function(){
 'use strict';
 const cfg={"timeZone":"Asia/Jakarta","dateOffset":"+07:00","timeLabel":"WIB","pageSize":20,"labelsSelector":"a[href*=\"/search/label/\"]","accent":"","ink":""};
 function start(){
  const root=document.querySelector('[data-tb-news-index]');
  if(!root||!window.TBNewsIndex)return;
  try{
   new Intl.DateTimeFormat('id-ID',{timeZone:cfg.timeZone}).format(new Date());
   const labels=Array.from(document.querySelectorAll(cfg.labelsSelector)).map(a=>{
    try{const u=new URL(a.getAttribute('href'),location.origin),prefix='/search/label/';
     return u.origin===location.origin&&u.pathname.startsWith(prefix)?decodeURIComponent(u.pathname.slice(prefix.length)):'';
    }catch(e){return '';}
   }).filter(Boolean);
   if(cfg.accent)root.style.setProperty('--tbni-accent',cfg.accent);
   if(cfg.ink)root.style.setProperty('--tbni-ink',cfg.ink);
   window.TBNewsIndex.mount(root,{labels,timeZone:cfg.timeZone,dateOffset:cfg.dateOffset,timeLabel:cfg.timeLabel,pageSize:cfg.pageSize});
  }catch(error){
   root.hidden=true;document.documentElement.classList.remove('has-tb-news-index');
   console.warn('TemaBlogger: indeks belum dapat disiapkan; arsip native tetap tersedia.',error);
  }
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

